/**
* Generates ONLY the L, C, and H component CSS variables for a theme.
*
* @param {String} $theme-name - 'light' or 'dark'.
* @param {String} $fallback-level - 'set' | 'pax' | 'full'. Controls the fallback depth.
*/

/**
* Generates ONLY the composite --color-base variables from the LCH components.
* This should be used in a context where the LCH variables from above already exist.
*
* @param {String} $theme-name - 'light' or 'dark'.
*/
.theme-light,
.is-mobile.theme-light {
  --ch-color-base-d-l-00: var(--ch-color-base-d-l-00-set, 13%);
  --ch-color-base-d-c-00: var(--ch-color-base-d-c-00-set, 0);
  --ch-color-base-d-h-00: var(--ch-color-base-d-h-00-set, 0);
