  --ch-color-base-d-c-10: var(--ch-color-base-d-c-10-set, 0);
  --ch-color-base-d-h-10: var(--ch-color-base-d-h-10-set, 0);
  --ch-color-base-d-l-15: var(--ch-color-base-d-l-15-set, 18%);
  --ch-color-base-d-c-15: var(--ch-color-base-d-c-15-set, 0);
  --ch-color-base-d-h-15: var(--ch-color-base-d-h-15-set, 0);
