/*
This correctly generates the base themes to be ready for your preset,
pax, and tmp variables, which will be defined in other files/stylesheets.
*/
.theme-light {
  --color-red-2: oklch(from var(--color-red) calc(l - 0.1) c calc(h + 4));
  --text-error-hover: var(--color-red-2);
  --background-modifier-message: rgb(0 0 0 / 80%);
  --background-primary: var(--color-base-00);
  --background-primary-alt: var(--color-base-10);
  --background-secondary: var(--color-base-20);
  --background-secondary-alt: var(--color-base-25);
  --interactive-normal: var(--color-base-20);
  --interactive-hover: var(--color-base-30);
  --interactive-focus: var(--color-base-40);
  --background-modifier-border: var(--color-base-35);
  --background-modifier-border-hover: var(--color-base-40);
  --background-modifier-border-focus: var(--color-base-45);
  --text-normal: var(--color-base-100);
  --text-muted: var(--color-base-60);
  --text-faint: var(--color-base-45);
  --text-highlight-bg: var(--col-highlight-0);
  --text-highlight-bg-active: var(--col-highlight-1);
  --text-selection: var(--color-selection);
  --code-background: var(--color-base-15);
  --background-modifier-form-field: var(--color-base-05);
  --background-modifier-active-hover: oklch(from var(--color-accent) l c h / 10%);
}

.theme-dark {
  --color-red-2: oklch(from var(--color-red) calc(l - 0.1) c calc(h + 4));
  --text-error-hover: var(--color-red-2);
  --background-modifier-message: rgb(0 0 0 / 80%);
  --background-primary: var(--color-base-00);
  --background-primary-alt: var(--color-base-10);
  --background-secondary: var(--color-base-20);
  --background-secondary-alt: var(--color-base-25);
