}

body:is(.ssopt-exclude-titlebar-buttons).is-hidden-frameless:is(.mod-windows, .mod-linux) .titlebar {
  display: none;
}

body:is(.ssopt-exclude-titlebar-buttons):is(.theme-light, .theme-dark) {
  --frame-right-space: 0;
}

