/* ---------- diff ---------- */
.diff-line.mod-left {
  background-color: oklch(from var(--background-modifier-error) l c h/20%);
}

.diff-line.mod-left .diff-changed {
  background-color: oklch(from var(--background-modifier-error) l c h/40%);
}

.diff-line.mod-right {
  background-color: oklch(from var(--background-modifier-success) l c h/20%);
}

.diff-line.mod-right .diff-changed {
  background-color: oklch(from var(--background-modifier-success) l c h/40%);
}

/* ---------- search / replace inputs ---------- */
.document-search-input.mod-no-match,
.document-replace-input.mod-no-match {
  background-color: oklch(from var(--background-modifier-error) l c h/20%);
}

@media (hover: hover) {
  .document-search-input.mod-no-match:hover,
  .document-replace-input.mod-no-match:hover {
    background-color: oklch(from var(--background-modifier-error) l c h/20%);
  }
}

/* ---------- PDF find-bar ---------- */
.pdf-findbar .mod-not-found {
  --background-modifier-form-field: oklch(from var(--background-modifier-error) l c h / 10%);
  --background-modifier-border-focus: oklch(from var(--background-modifier-error) l c h / 60%);
}

/* ---------- annotation highlight ---------- */
.annotationLayer .mod-focused {
  background-color: oklch(from var(--text-highlight-bg) l c h/10%);
  border: var(--size-4-1) solid oklch(from var(--text-highlight-bg) l c h/80%);
}

/* ---------- callouts ---------- */
.callout {
  border-color: oklch(from var(--callout-color) l c h/var(--callout-border-opacity));
  background-color: oklch(from var(--callout-color) l c h/10%);
}

.metadata-error-container {
  background-color: oklch(from var(--callout-error) l c h/10%);
}

@media (hover: hover) {
  .metadata-property-warning-icon:hover {
    background-color: oklch(from var(--color-orange) l c h/15%);
  }
}

/* ---------- file tree ---------- */
.file-tree .mod-new.is-selected {
  background-color: oklch(from var(--background-modifier-success) l c h/20%);
}

.file-tree .mod-deleted.is-selected,
.file-tree .mod-to-delete.is-selected {
  background-color: oklch(from var(--background-modifier-error) l c h/20%);
}

/* ---------- publish upload list ---------- */
.publish-upload-item::before {
  background-color: oklch(from var(--background-modifier-success) l c h/20%);
}

.publish-upload-item.mod-failed::before {
  background-color: oklch(from var(--background-modifier-error) l c h/20%);
}

/* ---------- canvas ---------- */
.canvas-node-placeholder::after {
  background-color: oklch(from var(--canvas-color) l c h/10%);
}

.canvas-node.is-themed .canvas-node-container {
  border-color: oklch(from var(--canvas-color) l c h/70%);
