  --bold-color: var(--bold-color-light, inherit);
  --italic-color: var(--italic-color-light, inherit);
}

.theme-dark {
  --bold-color: var(--bold-color-dark, inherit);
  --italic-color: var(--italic-color-dark, inherit);
}

/* X101-0B | Legacy width-vll from ED01 Variable Line Lengths */
.theme-light, .theme-dark {
  --width-vll: 700px;
  --file-line-width: var(--width-vll);
} /* setting a default for width-vll */

/* X101-0C | Image radius */
