  --radius-image: var(--radius-s);
}

img {
  border-radius: var(--radius-image);
}

/* X101-1 | Remove setting accent color in Settings > Appearance */
.modal.mod-settings .vertical-tab-content .setting-group .setting-item:nth-of-type(2) > .setting-item-control > .clickable-icon > .lucide-rotate-ccw {
