  display: none;
}

.modal.mod-settings .vertical-tab-content .setting-group .setting-item:nth-of-type(2) > .setting-item-control input[type="color"] {
  display: grid;
  width: fit-content;
  height: fit-content; /* forces it to take full space */
  visibility: hidden;
  pointer-events: none; /* so that the color thingy won't appear */
  grid-template-rows: 1fr 1fr 0;
}

.modal.mod-settings .vertical-tab-content .setting-group .setting-item:nth-of-type(2) > .setting-item-control input[type="color"]::before {
  position: relative;
  font-family: var(--font-interface);
  font-size: var(--font-ui-smaller);
  color: var(--text-error);
  visibility: visible;
  content: "The accent colour is overriden by the theme.";
  font-weight: bold;
  white-space: pre-wrap; /* breaks the lines into two */
  grid-row: 1/2;
}

.modal.mod-settings .vertical-tab-content .setting-group .setting-item:nth-of-type(2) > .setting-item-control input[type="color"]::after {
  position: relative;
