/* ────────────────────────────────────────────────────────────────────────────
>> FONT SIZE
──────────────────────────────────────────────────────────────────────────── */
body {
  --cssc-latex-font-size: 14pt;
  --cssc-latex-font-reading: "MathJax Main", "MJXZERO", "MJXTEX";
  --cssc-latex-font-source: "DM Mono" ,"MathJax Main", "MJXZERO", "MJXTEX";
  --cssc-latex-text-indent: 0em;
}

.latex.markdown-preview-view {
  font-family: var(--cssc-latex-font-reading);
  font-size: var(--cssc-latex-font-size);
  letter-spacing: 0.01rem;
}

.latex.mod-cm6.cm-s-obsidian .cm-contentContainer,
.latex .cm-header.cm-header {
  font-family: var(--cssc-latex-font-source);
  font-size: var(--cssc-latex-font-size);
  letter-spacing: 0.01rem;
}

/* ────────────────────────────────────────────────────────────────────────────
>> LINE HEIGHT
──────────────────────────────────────────────────────────────────────────── */
.latex.markdown-preview-view table {
  line-height: 100%;
}

/* ────────────────────────────────────────────────────────────────────────────
>> DIFFERENT HEADING STYLE
──────────────────────────────────────────────────────────────────────────── */
.latex :is(h1, h2, h3, h4, h5, h6) {
  font-family: var(--cssc-latex-font-reading);
  line-height: 1em;
}

:is(.latex.markdown-preview-view,
.latex.mod-cm6.cm-s-obsidian .cm-contentContainer) {
  text-align: justify;
  text-justify: inter-word;
}

/* ────────────────────────────────────────────────────────────────────────────
>> P
──────────────────────────────────────────────────────────────────────────── */
.latex p {
  text-indent: var(--cssc-latex-text-indent);
}

/* ────────────────────────────────────────────────────────────────────────────
>> BLOCKQUOTES
──────────────────────────────────────────────────────────────────────────── */
.latex blockquote {
  background-color: transparent;
  border: none;
  border-radius: 0;
  padding-left: 2rem;
  padding-right: 2rem;
}

/* ────────────────────────────────────────────────────────────────────────────
>> CODEBLOCKS
──────────────────────────────────────────────────────────────────────────── */
.latex :is(.theme-light :not(pre) > code[class*="language-"], .theme-light pre[class*="language-"]) {
  background-color: transparent;
  border-top: 0.1rem solid black;
  border-bottom: 0.1rem solid black;
  border-radius: 0;
}

/* ────────────────────────────────────────────────────────────────────────────
>> HEADERS
──────────────────────────────────────────────────────────────────────────── */
.latex .cm-s-obsidian .cm-header,
.latex :is(h1, h2, h3, h4, h5, h6),
.latex :is(.HyperMD-header-1.cm-line,
.HyperMD-header-2.cm-line,
.HyperMD-header-3.cm-line,
.HyperMD-header-4.cm-line,
.HyperMD-header-5.cm-line,
.HyperMD-header-6.cm-line),
.latex .cm-header.cm-header {
  color: var(--text-normal);
  background-color: transparent;
}

/* ────────────────────────────────────────────────────────────────────────────
>> CALLOUT INNER TITLE
──────────────────────────────────────────────────────────────────────────── */
.latex .callout-title-inner {
  font-family: var(--cssc-latex-font-reading);
}

/* ────────────────────────────────────────────────────────────────────────────
>> FIX FOR BREADCRUMB TRAIL GRID 
──────────────────────────────────────────────────────────────────────────── */
.latex div.BC-trail-grid.BC-trail-grid.BC-trail-grid {
  text-align: initial;
}

.latex .cm-cursor {
  height: 10px;
}

/* ────────────────────────────────────────────────────────────────────────────
>> TABLES (READING MODE) | I HAVE NO PATIENCE FOR A CSSCLASS, !IMPORTANT IT IS
──────────────────────────────────────────────────────────────────────────── */
.body {
  --cssc-latex-table-preview-font-size: 1em;
  --cssc-latex-table-editor-font-size: 0.8em;
}

.latex table {
  border-top: 0.1rem solid black;
  border-bottom: 0.1rem solid black;
}

.latex table, .latex th, .latex td {
  border-left: none !important;
  border-right: none !important;
  margin-left: auto;
  margin-right: auto;
  font-size: var(--cssc-latex-table-preview-font-size);
}

.latex th {
  background-color: transparent !important;
  text-align: center;
}

/* ────────────────────────────────────────────────────────────────────────────
>> TABLES (LIVE PREVIEW) | RESET ".table-lp-magic" for latex cssclass 
──────────────────────────────────────────────────────────────────────────── */

