/* ────────────────────────────────────────────────────────────────────────────
>> {to fix} EQUATION NUMBERS | INCREMENTAL
──────────────────────────────────────────────────────────────────────────── */
.latex {
  counter-reset: math-block;

  /* to center */
}

.latex .math-block {
  display: flex;
  justify-content: space-between;
  align-items: center;
  counter-increment: math-block;
}

.latex .math-block::before {
  content: "(" counter(math-block) ")";
  visibility: hidden;
}

.ssopt-cssc-latex-counter-brackets .latex .math-block::before {
  content: "[" counter(math-block) "]";
}

.ssopt-cssc-latex-counter-plain .latex .math-block::before {
  content: "" counter(math-block) "";
}

.latex .math-block::after {
  content: "(" counter(math-block) ")";
}

.ssopt-cssc-latex-counter-brackets .latex .math-block::after {
  content: "[" counter(math-block) "]";
}

.ssopt-cssc-latex-counter-plain .latex .math-block::after {
  content: "" counter(math-block) "";
}

/* ────────────────────────────────────────────────────────────────────────────
>> FIX PADDINGS
──────────────────────────────────────────────────────────────────────────── */
.latex .markdown-preview-section :where(h1, h2, h3, h4, h5, h6) {
  padding-left: 0;
}

/* ────────────────────────────────────────────────────────────────────────────
>> FIX COLOURS
──────────────────────────────────────────────────────────────────────────── */
