body {
  --cssc-banner-height: 200px;
  --cssc-banner-residual: 0px;
  --cssc-banner-gradient-mask: linear-gradient(to bottom,
  black 0%,
  black 50%,
  oklch(0% 0 0deg / 80%) 75%,
  oklch(0% 0 0deg / 50%) 80%,
  oklch(0% 0 0deg / 30%) 85%,
  oklch(0% 0 0deg / 15%) 90%,
  oklch(0% 0 0deg / 8%) 95%,
  transparent 100%
  ) ;
}

/* Reading Mode */
@container reading-mode (min-width: 0) {
  .markdown-preview-view:where(.banner) .markdown-preview-section {
    display: flex;
    flex-direction: column;
  }

  .markdown-preview-view:where(.banner) .mod-frontmatter + .el-p:has(img) {
    order: -1;
    height: var(--cssc-banner-height);
    margin: calc(-1 * var(--file-margins)) calc(-1 * var(--file-margins)) var(--cssc-banner-residual);
  }

  .markdown-preview-view:where(.banner) .mod-frontmatter + .el-p:has(img) p {
    margin-left: 0;
  }

  .markdown-preview-view:where(.banner) .mod-frontmatter + .el-p:has(img) img {
    width: 100%;
    object-fit: cover;
    object-position: 50% 50%;
    height: var(--cssc-banner-height);
    mask: var(--cssc-banner-gradient-mask);
  }
}

/* Markdown Live Preview */
.banner.is-live-preview .cm-sizer {
  padding-top: calc(var(--cssc-banner-height) - var(--file-margins) + var(--cssc-banner-residual));
}

.banner.is-live-preview .cm-contentContainer > .cm-content > :nth-child(1 of .image-embed) {
  position: relative;
  display: contents;

  /* height: 18px; how do I fix the line number clumping together? */
}

.banner.is-live-preview .cm-contentContainer > .cm-content > :nth-child(1 of .image-embed) img {
  position: absolute;
  top: 0;
  left: 0;
  object-fit: cover;
  object-position: 50% 50%;
  width: 100%;
  height: var(--cssc-banner-height);
  mask: var(--cssc-banner-gradient-mask);
}

/* Print? */
.print .banner {
  padding-top: var(--cssc-banner-height);
}

.print .banner .mod-frontmatter + div p:first-of-type img {
  position: absolute;
  top: 0;
  left: 0;
  object-fit: cover;
  object-position: 50% 50%;
  width: 100%;
  height: var(--cssc-banner-height);
  mask: var(--cssc-banner-gradient-mask);
}

